        if (window.BSA?.mobileKeyboard?.reset) window.BSA.mobileKeyboard.reset();
        if (typeof window.resetLoadingOverlay === 'function') window.resetLoadingOverlay();
        else if (typeof window.hideLoading === 'function') window.hideLoading();
